32	 */
33	@SpringBootTest
34	@Import(FixedClockTestConfig.class)
35	class RaceServiceH2Test extends AbstractRaceH2Test {
36	
37	    private static final String RACE = "race-1";
38	
39	    @Autowired
40	    private RaceService raceService;
41	
