                        "pair-1", "a", "b", 0L, 1000L)),
                "op-test", "req-enable"));
        raceService.submitSamples(RACE, "a", syntheticSamples(4, "req-sa", 3_000));
        raceService.submitSamples(RACE, "b", syntheticSamples(5, "req-sb", 2_000));
        return 6;
    }

    @Test
    void 封榜要求全部追逐对有当前裁定并冻结完整点与交会分数() {
        int version = seedPursuitWithTrajectories();
